function FactRotator() {
  const [i, setI] = useState(0);
  useEffect(() => {
    const t = setInterval(() => setI((v) => (v + 1) % FACTS.length), 4200);
    return () => clearInterval(t);
  }, []);
  return (
    <div className="rounded-2xl p-6 sm:p-8 h-full flex flex-col" style={{ background: C.darkAlt, border: "1px solid rgba(255,255,255,0.08)" }}>
      <div className="flex items-center gap-2 mb-5">
        <span className="text-lg">💡</span>
        <h3 className="font-medium" style={{ color: "#F5F6FA", fontFamily: "'Space Grotesk', sans-serif" }}>Random dev fact</h3>
      </div>
      <div className="flex-1 flex items-center">
        <p key={i} className="text-base leading-relaxed fact-fade" style={{ color: "#C7CAF5" }}>
          {FACTS[i]}
        </p>
      </div>
      <div className="flex gap-1.5 mt-6">
        {FACTS.map((_, idx) => (
          <span key={idx} className="h-1 rounded-full" style={{ width: idx === i ? 20 : 8, background: idx === i ? C.amber : "rgba(255,255,255,0.15)", transition: "all 0.3s ease" }} />
        ))}
      </div>
      <style>{`
        .fact-fade { animation: factFade 0.5s ease; }
        @keyframes factFade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
        @media (prefers-reduced-motion: reduce) { .fact-fade { animation: none; } }
      `}</style>
    </div>
  );
}


function BugGame() {
  const [state, setState] = useState("idle"); // idle | playing | over
  const [score, setScore] = useState(0);
  const [best, setBest] = useState(0);
  const [time, setTime] = useState(20);
  const [bugs, setBugs] = useState([]);
  const areaRef = useRef(null);
  const spawnRef = useRef(null);
  const tickRef = useRef(null);
  const idRef = useRef(0);

  const addBug = useCallback(() => {
    const id = idRef.current++;
    const x = 6 + Math.random() * 84;
    const y = 10 + Math.random() * 72;
    setBugs((b) => [...b, { id, x, y }]);
    setTimeout(() => setBugs((b) => b.filter((bug) => bug.id !== id)), 850);
  }, []);

  const start = () => {
    setScore(0);
    setTime(20);
    setBugs([]);
    setState("playing");
    spawnRef.current = setInterval(addBug, 650);
    tickRef.current = setInterval(() => {
      setTime((t) => {
        if (t <= 1) {
          clearInterval(spawnRef.current);
          clearInterval(tickRef.current);
          setBugs([]);
          setState("over");
          return 0;
        }
        return t - 1;
      });
    }, 1000);
  };

  const squash = (id) => {
    setBugs((b) => b.filter((bug) => bug.id !== id));
    setScore((s) => {
      const ns = s + 1;
      setBest((bst) => Math.max(bst, ns));
      return ns;
    });
  };

  useEffect(() => () => {
    clearInterval(spawnRef.current);
    clearInterval(tickRef.current);
  }, []);

  return (
    <div className="rounded-2xl p-6 sm:p-8" style={{ background: C.darkAlt, border: "1px solid rgba(255,255,255,0.08)" }}>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-5">
        <div className="flex items-center gap-2">
          <Bug size={18} style={{ color: C.amber }} />
          <h3 className="font-medium" style={{ color: "#F5F6FA", fontFamily: "'Space Grotesk', sans-serif" }}>
            Squash the Bug
          </h3>
        </div>
        <div className="flex items-center gap-4 text-sm" style={{ fontFamily: "'JetBrains Mono', monospace", color: "#9A9DB2" }}>
          <span>Score: <b style={{ color: state === "playing" ? C.amber : "#F5F6FA", transition: "color 0.2s" }}>{score}</b></span>
          <span className="flex items-center gap-1"><Trophy size={13} style={{ color: C.amber }} /> {best}</span>
          {state === "playing" && <span style={{ color: time <= 5 ? "#F0806A" : "#9A9DB2" }}>{time}s</span>}
        </div>
      </div>

      <div
        ref={areaRef}
        className="relative rounded-xl overflow-hidden select-none game-grid"
        style={{ height: 220, background: "radial-gradient(circle at 30% 20%, rgba(68,83,224,0.25), transparent 60%), radial-gradient(circle at 80% 80%, rgba(232,163,61,0.15), transparent 55%), #14172400", border: "1px solid rgba(255,255,255,0.08)" }}
      >
        {state !== "playing" && (
          <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 px-6 text-center z-10">
            <p className="text-sm" style={{ color: "#B7BACD" }}>
              {state === "idle" ? "Ship happens. Click the bugs before they escape." : `Time's up — you squashed ${score}.`}
            </p>
            <button
              onClick={start}
              className="flex items-center gap-2 px-5 py-2.5 rounded-full text-sm font-medium transition-transform hover:scale-105"
              style={{ background: C.amber, color: C.ink }}
            >
              <RotateCcw size={14} /> {state === "idle" ? "Start" : "Play again"}
            </button>
          </div>
        )}
        {bugs.map((b) => (
          <button
            key={b.id}
            onClick={() => squash(b.id)}
            aria-label="squash bug"
            className="absolute bug-pop flex items-center justify-center rounded-full"
            style={{ left: `${b.x}%`, top: `${b.y}%`, width: 34, height: 34, background: C.ink, border: `2px solid ${C.amber}`, boxShadow: `0 0 14px ${C.amber}66` }}
          >
            <Bug size={16} style={{ color: C.amber }} />
          </button>
        ))}
      </div>
      <style>{`
        .game-grid { background-image: linear-gradient(rgba(255,255,255,0.04) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.04) 1px, transparent 1px); background-size: 24px 24px; }
        .bug-pop { animation: bugPop 0.85s linear forwards; }
        @keyframes bugPop {
          0% { transform: scale(0.4); opacity: 0; }
          15% { transform: scale(1); opacity: 1; }
          85% { transform: scale(1); opacity: 1; }
          100% { transform: scale(0.5); opacity: 0; }
        }
      `}</style>
    </div>
  );
}


