function StackExplorer() {
  const [i, setI] = useState(0);
  const [auto, setAuto] = useState(true);
  useEffect(() => {
    if (!auto) return;
    const t = setInterval(() => setI((v) => (v + 1) % LAYERS.length), 3800);
    return () => clearInterval(t);
  }, [auto]);
  const L = LAYERS[i];
  return (
    <div>
      <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 mb-4">
        {LAYERS.map((l, idx) => {
          const on = idx === i;
          return (
            <button
              key={l.label}
              onClick={() => { setI(idx); setAuto(false); }}
              className="text-left rounded-xl p-4 transition-all duration-300"
              style={{
                background: on ? "rgba(139,108,255,0.12)" : C.surface,
                border: `1px solid ${on ? C.violet : C.line}`,
                boxShadow: on ? "0 0 32px rgba(139,108,255,0.18)" : "none",
              }}
            >
              <div className="text-xs mb-3" style={{ fontFamily: MONO, color: on ? C.amber : C.faint }}>0{idx + 1}</div>
              <div className="text-sm font-medium" style={{ color: C.text }}>{l.label}</div>
            </button>
          );
        })}
      </div>
      <SpotCard>
        <div key={i} className="fade-up p-6 sm:p-9 grid md:grid-cols-2 gap-8 items-center">
          <div>
            <div className="mb-3" style={{ fontFamily: SERIF, fontStyle: "italic", fontSize: "1.6rem", color: C.amber }}>{L.tag}</div>
            <p style={{ color: C.soft, lineHeight: 1.7 }}>{L.text}</p>
          </div>
          <div className="flex flex-wrap gap-2">
            {L.items.map((it) => (
              <Chip key={it} tone="violet">{it}</Chip>
            ))}
          </div>
        </div>
      </SpotCard>
    </div>
  );
}

